import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const [message, setMessage] = useState("");
  const [user, setUser] = useState(null);

  const scannerRef = useRef(null);
  const startedRef = useRef(false);

  useEffect(() => {
    const startScanner = async () => {
      if (startedRef.current) return;

      scannerRef.current = new Html5Qrcode("reader");

      try {
        await scannerRef.current.start(
          { facingMode: "environment" },
          { fps: 10, qrbox: 250 },

          (decodedText) => {
            console.log("QR SCANNED:", decodedText);

            verifyUser(decodedText);
          },

          (error) => {
            // ignore scan errors
          },
        );

        startedRef.current = true;
      } catch (err) {
        console.log("Scanner start error:", err);
      }
    };

    startScanner();

    return async () => {
      if (scannerRef.current && startedRef.current) {
        try {
          await scannerRef.current.stop();
          startedRef.current = false;
        } catch (err) {
          console.log("Stop error ignored");
        }
      }
    };
  }, []);

  // VERIFY USER
  const verifyUser = async (id) => {
    try {
      const res = await axios.get(`http://localhost:5000/verify-user/${id}`);

      if (res.data.success) {
        setUser(res.data.user);
        setMessage("✅ VERIFIED");
      } else {
        setUser(null);
        setMessage("❌ NOT REGISTERED");
      }
    } catch (err) {
      console.log(err);
      setMessage("⚠ SERVER ERROR");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin QR Scanner</h2>

      <div id="reader" style={{ width: "350px" }}></div>

      <h3>{message}</h3>

      {user && (
        <div>
          <p>Name: {user.name}</p>
          <p>College: {user.college_name}</p>
          <p>Phone: {user.phone}</p>
          <p>Event: {user.event_id}</p>
        </div>
      )}
    </div>
  );
}

export default QRScanner;
